package daa;
import daa.graph.*;import daa.algorithms.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class GraphAlgorithmsTest {@Test void kahnDetectsCycle(){Graph g=new Graph(3,true);g.addEdge(0,1,1);g.addEdge(1,2,1);assertFalse(Kahn.sort(g).hasCycle());g.addEdge(2,0,1);assertTrue(Kahn.sort(g).hasCycle());}@Test void kosarajuFindsTwoComponents(){Graph g=new Graph(4,true);g.addEdge(0,1,1);g.addEdge(1,0,1);g.addEdge(1,2,1);g.addEdge(2,3,1);g.addEdge(3,2,1);assertEquals(2,Kosaraju.find(g).components().size());}@Test void dagPathsAllowNegativeWeights(){Graph g=new Graph(4,true);g.addEdge(0,1,3);g.addEdge(0,2,5);g.addEdge(1,2,-4);g.addEdge(2,3,2);var r=DagShortestPath.compute(g);assertEquals(-1,r.distances()[2]);assertEquals(1,r.distances()[3]);assertEquals(java.util.List.of(0,1,2,3),r.pathTo(3));}@Test void iterativeSccHandlesLongPath(){Graph g=new Graph(100000,true);for(int i=0;i<99999;i++)g.addEdge(i,i+1,1);assertEquals(100000,Kosaraju.find(g).components().size());}}
